bool ScriptSession::cancelCombat(UnitState& u) {u.cargoDrop.reset();cancelMilitiaOrder(u);cancelShadowMeld(u);cancelGather(u);cancelWork(u);auto home=u.combat.home;auto ready=u.combat.nextAttack;auto revision=u.combat.revision+1;u.combat={};u.combat.home=home;u.combat.nextAttack=ready;u.combat.revision=revision;auto id=u.handle;auto owner=u.owner;bool ok=cancelCast(u,true);return ok && alive(id,NativeKind::Unit) && units_.at(id)->combat.revision==revision && units_.at(id)->owner==owner;}
bool ScriptSession::chase(UnitState& u,WorldPoint target,float standoff,bool allowPartial) {
    float dx=number(target.x)-number(u.x),dy=number(target.y)-number(u.y),distance=std::hypot(dx,dy);if(distance<=standoff){u.route.clear();u.waypoint=0;return true;}if(u.stationaryBuilding() || u.rooted() || u.stunned() || number(u.currentMoveSpeed())<=0)return false;WorldPoint end{real(number(target.x)-dx/distance*standoff),real(number(target.y)-dy/distance*standoff)};end=requireWorld().clamp(end);auto path=u.pathing?requireWorld().route({u.x,u.y},end,u.collision,pathMovement(u.movementType),allowPartial):std::vector<WorldPoint>{end};if(path.empty())return false;u.route=std::move(path);u.waypoint=0;u.pathingRevision=requireWorld().blockingRevision();u.combat.repath=simulationTime_+.25;if(u.animation=="Attack"){u.animation.clear();u.animationIndex.reset();u.animationTime=0;++u.animationGeneration;}return true;
}
bool ScriptSession::attackUnit(std::uint32_t source,std::uint32_t target,bool forced,std::uint32_t ability) {
    if(source==target || !alive(source,NativeKind::Unit) || !alive(target,NativeKind::Unit))return false;auto u=units_.at(source),victim=units_.at(target);auto previousTarget=u->combat.target;bool previousPending=previousTarget==target && u->combat.targetAcquiredPending;if(u->paused || u->stunned() || u->spinning() || u->construction || u->unsummon || u->hidden() || u->removing || number(u->life)<=0 || victim->hidden() || !unitVisibleTo(target,u->owner) || (!forced && !enemy(u->owner,victim->owner)))return false;auto weapon=weaponFor(*u,*victim);if(!weapon)return false;auto w=unitWeapon(*u,*weapon);auto orb=ability?attackOrb(*u,*victim,ability):nullptr;if(ability && !orb)return false;if(orb)orbWeapon(w,*orb);float range=w.range+u->collision+victim->collision;float distance=std::hypot(number(victim->x)-number(u->x),number(victim->y)-number(u->y));if(distance<=range && distance>=w.minimumRange){u->route.clear();u->waypoint=0;}else if(u->stationaryBuilding() || !chase(*u,{victim->x,victim->y},std::max(0.f,range-8)))return false;if(!cancelCombat(*u) || (ability && !attackOrb(*u,*victim,ability)))return false;u->combat.target=target;u->combat.targetAcquiredPending=previousTarget!=target || previousPending;u->combat.attackAbility=ability;u->combat.forced=forced;u->combat.repath=simulationTime_+.25;u->currentOrder=orb?orb->order:851983;u->holding=false;ScriptContext context;context.issuedOrder=u->currentOrder;context.orderTarget=target;unitEvent(source,40,77,context);return true;
}
bool ScriptSession::attackMove(std::uint32_t source,WorldPoint point,bool patrol,std::optional<WorldPoint> destination) {
    if(!alive(source,NativeKind::Unit))return false;auto u=units_.at(source);if(u->paused || u->stunned() || u->construction || u->unsummon || u->hidden() || u->removing || u->stationaryBuilding() || number(u->life)<=0 || number(u->moveSpeed)<=0)return false;point=requireWorld().clamp(point);auto end=destination?requireWorld().clamp(*destination):point;if(!chase(*u,end,0,true))return false;if(!u->route.empty())end=u->route.back();auto start=WorldPoint{u->x,u->y};if(!cancelCombat(*u))return false;u->combat.attackMove=end;if(patrol){u->combat.patrolStart=start;u->combat.patrolEnd=end;}u->currentOrder=patrol?851990:851983;u->holding=false;ScriptContext context;context.issuedOrder=u->currentOrder;context.orderPoint=point;unitEvent(source,39,76,context);return true;
}
bool ScriptSession::targetOrder(std::uint32_t source,std::uint32_t target,std::uint32_t order) {
    if(!alive(source,NativeKind::Unit))return false;if(order==852047 && alive(target,NativeKind::Unit)){if(units_.at(target)->transport==source)return unloadUnit(source,target);if(unloadMineWorker(source,target))return true;}if(alive(target,NativeKind::Unit) && !unitVisibleTo(target,units_.at(source)->owner))return false;if(order==852039)return queueRevival(source,target);if(castOrder(source,order,target))return true;if(order==851971 && (enterWaygate(source,target,order) || smartCouple(source,target) || smartRecharge(source,target)))return true;if(!alive(source,NativeKind::Unit))return false;auto u=units_.at(source);if(u->paused || u->stunned() || u->construction || u->unsummon || u->hidden() || u->removing || number(u->life)<=0)return false;if(u->spinning()){if((order!=851971 && order!=851986 && order!=851983) || !alive(target,NativeKind::Unit) || target==source)return false;auto other=units_.at(target);if(other->hidden() || other->removing || number(other->life)<=0 || !chase(*u,{other->x,other->y},u->collision+other->collision+64) || !cancelCombat(*u))return false;u->combat.follow=target;u->combat.repath=simulationTime_+.25;u->currentOrder=order;u->holding=false;ScriptContext context;context.issuedOrder=order;context.orderTarget=target;unitEvent(source,40,77,context);return true;}if(u->morphed()){if((order!=851971 && order!=851986) || !alive(target,NativeKind::Unit) || target==source)return false;auto other=units_.at(target);if(other->hidden() || other->removing || number(other->life)<=0 || !chase(*u,{other->x,other->y},u->collision+other->collision+64) || !cancelCombat(*u))return false;u->combat.follow=target;u->combat.repath=simulationTime_+.25;u->currentOrder=order;u->holding=false;ScriptContext context;context.issuedOrder=order;context.orderTarget=target;unitEvent(source,40,77,context);return true;}if(alive(target,NativeKind::Destructable)){if(order==851983)return attackWidget(source,target);auto d=destructables_.at(target);if(order==851980 || (order==851971 && (u->stationaryBuilding() || factories_.contains(source))))return setRally(source,d->position,target);return (order==851971 || order==852018) && harvestTree(source,target);}if(alive(target,NativeKind::Unit)){auto other=units_.at(target);if(order==851971 && number(other->life)<=0 && corpseCarrier(source)){auto load=sourceAbility(*u,"Amel");return load.first && castSpell(source,load.first,target);}if((order==851971 || order==852043) && cargoInfo(*other) && !corpseCarrier(target))return boardUnit(source,target,order);if(order==852147 || order==852148)return entangleMine(source,target,order==852148);if((order==851971 || order==852024 || order==852161 || order==852202) && repair(source,target))return true;if(order==852024 || order==852161 || order==852202)return false;if((order==851971 || order==852018) && harvest(source,target))return true;if((order==851971 || order==852020) && (u->carriedGold || u->carriedLumber) && returnResources(source,target))return true;if(order==852018 || order==852020)return false;if(order==851980 || (order==851971 && (u->stationaryBuilding() || factories_.contains(source))))return setRally(source,{other->x,other->y},target);if(order==851983 || (order==851971 && enemy(u->owner,other->owner)))return attackUnit(source,target,order==851983);if((order!=851971 && order!=851986) || source==target || other->removing || number(other->life)<=0 || other->hidden() || !chase(*u,{other->x,other->y},u->collision+other->collision+64))return false;if(!cancelCombat(*u))return false;u->combat.follow=target;u->currentOrder=order;u->holding=false;}else if(alive(target,NativeKind::Item)){if(order==851983)return attackWidget(source,target);auto item=items_.at(target);if((order!=851971 && order!=851981) || item->holder || !item->visible || u->illusion || (!inventorySize(*u) && definitions().number(item->type,"ItemData","powerup")==0) || !chase(*u,{item->x,item->y},96+u->collision))return false;if(!cancelCombat(*u))return false;u->combat.pickup=target;u->currentOrder=order;u->holding=false;}else return false;u->combat.repath=simulationTime_+.25;ScriptContext context;context.issuedOrder=order;context.orderTarget=target;unitEvent(source,40,77,context);return true;
}
void ScriptSession::bindCombatNatives() {
    auto order=[](const jass::Value& value){return value.text?orderId(*value.text):0u;};
    bind("IssueTargetOrder","boolean",{"unit","string","widget"},[this,order](auto& vm,auto a){clearPlayerOrders(a[0].bits);return vm.boolean(targetOrder(a[0].bits,a[2].bits,order(a[1])));});
    bind("IssueTargetOrderById","boolean",{"unit","integer","widget"},[this](auto& vm,auto a){clearPlayerOrders(a[0].bits);return vm.boolean(targetOrder(a[0].bits,a[2].bits,a[1].bits));});
    bind("GetAttacker","unit",{},[this](auto& vm,auto){return vm.handle("unit",contexts_.empty()?0:contexts_.back().attacker);});
    bind("GetEventTargetUnit","unit",{},[this](auto& vm,auto){return vm.handle("unit",contexts_.empty()?0:contexts_.back().eventTargetUnit);});
    bind("GetOrderTarget","widget",{},[this](auto& vm,auto){auto id=contexts_.empty()?0:contexts_.back().orderTarget;return vm.handle("widget",alive(id,NativeKind::Unit) || alive(id,NativeKind::Item) || alive(id,NativeKind::Destructable)?id:0);});
    bind("GetOrderTargetUnit","unit",{},[this](auto& vm,auto){auto id=contexts_.empty()?0:contexts_.back().orderTarget;return vm.handle("unit",alive(id,NativeKind::Unit)?id:0);});
    bind("GetOrderTargetDestructable","destructable",{},[this](auto& vm,auto){auto id=contexts_.empty()?0:contexts_.back().orderTarget;return vm.handle("destructable",alive(id,NativeKind::Destructable)?id:0);});
    bind("GetOrderTargetItem","item",{},[this](auto& vm,auto){auto id=contexts_.empty()?0:contexts_.back().orderTarget;return vm.handle("item",alive(id,NativeKind::Item)?id:0);});
}
